    async def my_user_account(
        self, **kwargs: Any
    ) -> Optional["MyUserAccountMyUserAccount"]:
        from .my_user_account import MyUserAccount

        query = gql("""
            query MyUserAccount {
              myUserAccount {
                id
                fullName
                publicName
                email
              }
            }
            """)
        variables: dict[str, object] = {}
        response = await self.execute(
            query=query, operation_name="MyUserAccount", variables=variables, **kwargs
        )
        data = self.get_data(response)
        return MyUserAccount.model_validate(data).my_user_account

