    async def thread_participants(
        self,
        thread_id: str,
        first: Union[int | None, "UnsetType"] = UNSET,
        after: Union[str | None, "UnsetType"] = UNSET,
        last: Union[int | None, "UnsetType"] = UNSET,
        before: Union[str | None, "UnsetType"] = UNSET,
        **kwargs: Any,
    ) -> Optional["ThreadParticipantsThread"]:
        from .thread_participants import ThreadParticipants

        query = gql("""
            query ThreadParticipants($threadId: ID!, $first: Int, $after: String, $last: Int, $before: String) {
              thread(threadId: $threadId) {
                participants(first: $first, after: $after, last: $last, before: $before) {
                  edges {
                    node {
                      __typename
                      ... on UserActor {
                        ...UserActorFields
                      }
                      ... on CustomerActor {
                        ...CustomerActorFields
                      }
                      ... on DeletedCustomerActor {
                        ...DeletedCustomerActorFields
                      }
                      ... on SystemActor {
                        ...SystemActorFields
                      }
                      ... on MachineUserActor {
                        ...MachineUserActorFields
                      }
                    }
                    cursor
                  }
                  pageInfo {
                    hasNextPage
                    hasPreviousPage
                    startCursor
                    endCursor
                  }
                }
              }
            }

            fragment CustomerActorFields on CustomerActor {
              customerId
              customer {
                id
              }
            }

            fragment DeletedCustomerActorFields on DeletedCustomerActor {
              customerId
            }

            fragment MachineUserActorFields on MachineUserActor {
              machineUserId
              machineUser {
                id
              }
            }

            fragment SystemActorFields on SystemActor {
              systemId
              workflowExecutionId
              workflow {
                id
                name
              }
            }

            fragment UserActorFields on UserActor {
              userId
              user {
                id
              }
            }
            """)
        variables: dict[str, object] = {
            "threadId": thread_id,
            "first": first,
            "after": after,
            "last": last,
            "before": before,
        }
        response = await self.execute(
            query=query,
            operation_name="ThreadParticipants",
            variables=variables,
            **kwargs,
        )
        data = self.get_data(response)
        return ThreadParticipants.model_validate(data).thread

